r"""使用回報：把同事 session 遇到的執行問題寫成一份 Markdown，存在使用者「文件」\PCCES回報\。

只寫本機檔，不上傳、不寄出：由使用者自己打開檢查刪改，再用 LINE 傳給提供工具的同事（2026-11-23 使用者決定）。
模型給的文字先把這台的使用者資料夾與帳號名稱換成 <user>；單價、金額、工程名稱不寫進來靠工具說明與 pcces skill 要求模型，
這裡不猜數字。
"""

from __future__ import annotations

import os
import platform
import re
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from . import __version__

# 測試與驗收用：把回報資料夾改到暫存，不寫進真的「文件」。產品不設
REPORT_DIR_ENV = "PCX_REPORT_DIR"
FOLDER_NAME = "PCCES回報"
USER = "<user>"
MAX_PER_DAY = 99

# 帳號名稱太短或太通用時單獨換會把一般字詞換掉，就只換整段使用者資料夾（跟 build_plugin.py 外流檢查同一套門檻）
_GENERIC_ACCOUNTS = {"user", "users", "admin", "administrator", "owner", "guest", "public", "default", "test", "pc"}

HEADER = "送出前可自行檢查刪改"


class ReportError(Exception):
    """寫不出回報；訊息是使用者或模型的下一步。"""


@dataclass
class Report:
    summary: str
    attempts: list[str]
    expected: str
    actual: str
    user_words: str = ""

    def missing(self) -> list[str]:
        """必填但空白的欄位名（照工具參數名）。"""
        out = [n for n in ("summary", "expected", "actual") if not (getattr(self, n) or "").strip()]
        if not [a for a in (self.attempts or []) if (a or "").strip()]:
            out.insert(1, "attempts")
        return out


def documents_dir() -> Path:
    """使用者的「文件」：可能被 OneDrive 或群組原則重新導向，先問 Windows（CSIDL_PERSONAL），問不到才用 %USERPROFILE%\\Documents。"""
    try:
        import ctypes

        buf = ctypes.create_unicode_buffer(32768)
        if ctypes.windll.shell32.SHGetFolderPathW(None, 5, None, 0, buf) == 0 and buf.value:
            return Path(buf.value)
    except (AttributeError, OSError):
        pass
    return Path(os.environ.get("USERPROFILE") or Path.home()) / "Documents"


def report_dir() -> Path:
    env = os.environ.get(REPORT_DIR_ENV)
    return Path(env) if env else documents_dir() / FOLDER_NAME


def _home() -> str:
    return os.environ.get("USERPROFILE") or str(Path.home())


def scrub(text: str, home: str | None = None) -> str:
    """把使用者資料夾裡的帳號名稱換成 <user>：整段路徑（\\、/、JSON 跳脫三種寫法，不分大小寫）一律換，
    帳號名稱單獨出現時只在夠長、不通用時換，前後不接英數。"""
    home = (home or _home()).rstrip("\\/")
    name = Path(home).name
    if not name:
        return text
    for sep in ("\\\\", "\\", "/"):
        form = home.replace("\\", sep)
        text = re.sub(re.escape(form) + r"(?![A-Za-z0-9_])", lambda m: m.group(0)[: -len(name)] + USER,
                      text, flags=re.IGNORECASE)
    if len(name) >= (4 if name.isascii() else 2) and name.lower() not in _GENERIC_ACCOUNTS:
        text = re.sub(rf"(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_])", USER, text, flags=re.IGNORECASE)
    return text


def _pcces_status() -> str:
    # 只看安裝資料夾有沒有 PccesMain.exe（登錄檔＋預設位置），不連資料庫：連不上時要等逾時，不算便宜
    from .recalc import RecalcError, install_dir

    try:
        return f"這台有裝（{install_dir()}）"
    except RecalcError:
        return "這台沒找到 PCCES 4.3"
    except OSError as exc:
        return f"查不到（{exc.__class__.__name__}）"


def _runtime() -> str:
    # 開發時 src\pcx_mcp 往上兩層是專案資料夾（有 pyproject.toml）；plugin 裡是內附 Python 的 Lib\，沒有
    return "開發版" if (Path(__file__).resolve().parents[2] / "pyproject.toml").is_file() else "plugin"


def environment(now: datetime) -> list[tuple[str, str]]:
    tz = now.strftime("%z")
    tz = f"（UTC{tz[:3]}:{tz[3:]}）" if tz else ""
    win = f"Windows {platform.release()}（{platform.version()}"
    edition = getattr(platform, "win32_edition", lambda: None)()
    win += f"，{edition}）" if edition else "）"
    return [
        ("時間", now.strftime("%Y-%m-%d %H:%M:%S") + tz),
        ("外掛版本", f"pcces {__version__}（{_runtime()}）"),
        ("Windows", win),
        ("PCCES", _pcces_status()),
    ]


def _block(text: str) -> str:
    return "\n".join(line.rstrip() for line in text.strip().splitlines())


def render(r: Report, env_rows: list[tuple[str, str]]) -> str:
    out = [
        "# PCCES 工具使用回報",
        "",
        f"> {HEADER}：這份檔只存在你的電腦，不會自動送出。看一下有沒有單價、金額、工程名稱這類不想給的內容，"
        "刪掉或改掉之後，再用 LINE 傳給提供這套工具的同事。",
        "",
        "## 問題摘要",
        "",
        _block(r.summary),
        "",
        "## 做了哪些嘗試",
        "",
    ]
    steps = [a for a in r.attempts if (a or "").strip()]
    out += [f"{i}. " + _block(a).replace("\n", "\n   ") for i, a in enumerate(steps, 1)]
    out += ["", "## 期望與實際", "", "1. 期望：" + _block(r.expected).replace("\n", "\n   "),
            "2. 實際：" + _block(r.actual).replace("\n", "\n   ")]
    if (r.user_words or "").strip():
        out += ["", "## 使用者原話", "", *("> " + ln for ln in _block(r.user_words).splitlines())]
    out += ["", "## 環境（工具自動填）", "", "| 項目 | 內容 |", "| --- | --- |"]
    out += [f"| {k} | {v.replace('|', '／')} |" for k, v in env_rows]
    return scrub("\n".join(out) + "\n")


def write_report(r: Report, folder: Path | None = None, now: datetime | None = None) -> Path:
    """寫成 <資料夾>\\<YYYYMMDD>_<流水號>.md：獨占建立，已有同名檔就換下一個號碼，絕不覆蓋。
    UTF-8 帶 BOM、CRLF：同事用記事本或舊編輯器打開也不亂碼、不擠成一行。"""
    missing = r.missing()
    if missing:
        raise ReportError(f"{'、'.join(missing)} 不能是空的")
    now = now or datetime.now().astimezone()
    folder = folder or report_dir()
    data = ("﻿" + render(r, environment(now)).replace("\n", "\r\n")).encode("utf-8")
    folder.mkdir(parents=True, exist_ok=True)
    for n in range(1, MAX_PER_DAY + 1):
        p = folder / f"{now:%Y%m%d}_{n:02d}.md"
        try:
            with open(p, "xb") as f:
                f.write(data)
        except FileExistsError:
            continue
        return p
    raise ReportError(f"{folder} 裡同一天已有 {MAX_PER_DAY} 份回報，請使用者先把舊的傳出去或刪掉")
